{"type":"TRIP_UPDATE","trip_id":"trp_7Z3kY8","status":"MATCHED",
 "driver":{"id":"d_42","name":"Alex","vehicle":"Toyota Prius ABC123","rating":4.92},
 "eta_pickup_sec":180}

// driver arriving
{"type":"TRIP_UPDATE","trip_id":"trp_7Z3kY8","status":"DRIVER_ARRIVING",
 "driver_location":{"lat":...,"lng":...},"eta_pickup_sec":40}

